// ---------- Given ----------

// Reuses the same cached per-role session as steps/support/common.steps.ts's
// "User is logged in as {string}" — see that step and auth-setup.ts's
// getOrCreateRoleAuthState() for why (avoids repeated interactive logins tripping the
// live backend's login-attempt throttling). The guideEmail/ranchAdminEmail testData
// fields these steps originally fell back from are never populated by any CSV, so the
// fallback below is now the actual (and only) real confirmed QA account for each role,
// not a placeholder.
async function loginAsCachedRole(context: ScenarioContext, email: string, password: string): Promise<void> {
  const browser = getSharedBrowser();
  await context.context?.close();
  const authed = await getAuthenticatedPage(browser, email, password);
  context.context = authed.context;
  context.page = authed.page;
}

Given('Guide user is logged in', async function (this: ScenarioContext) {
  const email = (this.testData.guideEmail as string) ?? 'guidec01@gmail.com';
  await loginAsCachedRole(this, email, resolvePassword('GUIDE_PASSWORD'));
  this.testData.role = 'Guide';
});

Given('Guide user {string} is logged in', async function (this: ScenarioContext, guideEmail: string) {
  await loginAsCachedRole(this, guideEmail, resolvePassword('GUIDE_PASSWORD'));
  this.testData.role = 'Guide';
});

Given('Ranch Admin user is logged in', async function (this: ScenarioContext) {
  const email = (this.testData.ranchAdminEmail as string) ?? 'testauto10@yopmail.com';
  await loginAsCachedRole(this, email, resolvePassword('RANCH_ADMIN_PASSWORD'));
  this.testData.role = 'Ranch Admin';
});

Given('a valid new booking is submitted for ranch {string} with hunter {string}', async function (
  this: ScenarioContext,
  ranchName: string,
  hunterName: string,
) {
  await this.bookingPage.openNewBookingWizard();
  await this.bookingPage.selectBookingType('Hunting');
  await this.bookingPage.selectRanch(ranchName);
  await this.bookingPage.clickNext();
  await this.bookingPage.clickNext();
  await this.bookingPage.addHunter({
    fullName: hunterName,
    email: (this.testData.hunterEmail as string) ?? 'qa.hunter@ranchops-test.com',
    streetAddress: (this.testData.hunterAddress as string) ?? '100 QA Rd',
    city: (this.testData.hunterCity as string) ?? 'Austin',
    state: (this.testData.hunterState as string) ?? 'TX',
    zip: (this.testData.hunterZip as string) ?? '78701',
  });
  await this.bookingPage.clickNext();
  await this.bookingPage.clickNext();
  await this.bookingPage.submitBooking();
});

